// Generated by `npx @musikhood-dev/auth-client init` — this file is yours, edit freely.
import { isAuthErrorNamed } from '@musikhood-dev/auth-client'
import type {
  InvalidCredentialsError,
  LoginForbiddenError,
  MfaAlreadyEnabledError,
  MfaEnrollmentRequiredError,
  MfaInvalidCodeError,
  MfaRequiredError,
  MfaTokenExpiredError,
  PanelAccessDeniedError,
  SessionExpiredError,
  TooManyAttemptsError,
} from '@musikhood-dev/auth-client'

// User-facing texts of the auth flow (login, 2FA code step, step-up and enrollment dialogs).
export const MFA_TEXTS = {
  invalidCredentials: 'Nieprawidłowy email lub hasło.',
  loginForbidden: 'Brak dostępu do tego panelu.',
  loginFailed: 'Nie udało się zalogować. Spróbuj ponownie.',
  logoutFailed: 'Nie udało się wylogować.',
  invalidCode: 'Nieprawidłowy kod. Spróbuj ponownie.',
  codeReused: 'Ten kod został już użyty — poczekaj na następny w aplikacji.',
  tokenExpired: 'Sesja weryfikacji wygasła. Zaloguj się ponownie.',
  verifyFailed: 'Nie udało się zweryfikować kodu.',
  invalidPassword: 'Nieprawidłowe hasło.',
  alreadyEnabled: 'Weryfikacja dwuetapowa jest już włączona na tym koncie.',
  enrollmentFailed: 'Nie udało się przygotować konfiguracji 2FA.',
  recoveryCodeHint:
    'Po zalogowaniu skontaktuj się z administratorem, aby ponownie skonfigurować 2FA.',
} as const

// Error classes recognised by name. The package bundles each entry (`/react`, `/vue`)
// separately, so `instanceof` across entries can fail — the `name` field is reliable.
type AuthErrors = {
  InvalidCredentialsError: InvalidCredentialsError
  LoginForbiddenError: LoginForbiddenError
  MfaAlreadyEnabledError: MfaAlreadyEnabledError
  MfaEnrollmentRequiredError: MfaEnrollmentRequiredError
  MfaInvalidCodeError: MfaInvalidCodeError
  MfaRequiredError: MfaRequiredError
  MfaTokenExpiredError: MfaTokenExpiredError
  PanelAccessDeniedError: PanelAccessDeniedError
  SessionExpiredError: SessionExpiredError
  TooManyAttemptsError: TooManyAttemptsError
}

// Exact-name type guard (a subclass does NOT match its parent: MfaRequiredError is not
// treated as InvalidCredentialsError here).
export function isAuthError<K extends keyof AuthErrors>(
  error: unknown,
  name: K,
): error is AuthErrors[K] {
  return isAuthErrorNamed(error, name)
}

// Readable message for the attempt limit (429 + Retry-After).
export function formatRetryAfter(seconds: number | null): string {
  if (seconds === null) return 'Zbyt wiele prób. Spróbuj ponownie później.'
  if (seconds < 60) return `Zbyt wiele prób. Spróbuj ponownie za ${seconds} s.`
  return `Zbyt wiele prób. Spróbuj ponownie za ${Math.ceil(seconds / 60)} min.`
}

// Inline message for a failed 2FA code step (login / step-up). null = not an expected
// 2FA error (it is reported by the global `login-error` listener in lib/auth.ts).
export function mfaErrorMessage(error: unknown): string | null {
  if (isAuthError(error, 'MfaInvalidCodeError')) {
    return error.reason === 'reused' ? MFA_TEXTS.codeReused : MFA_TEXTS.invalidCode
  }
  if (isAuthError(error, 'MfaTokenExpiredError')) return MFA_TEXTS.tokenExpired
  if (isAuthError(error, 'TooManyAttemptsError')) return formatRetryAfter(error.retryAfter)
  return null
}

// Inline message for a failed password step of the login form.
export function loginErrorMessage(error: unknown): string {
  if (isAuthError(error, 'InvalidCredentialsError')) return MFA_TEXTS.invalidCredentials
  if (isAuthError(error, 'TooManyAttemptsError')) return formatRetryAfter(error.retryAfter)
  if (isAuthError(error, 'LoginForbiddenError') || isAuthError(error, 'PanelAccessDeniedError')) {
    return MFA_TEXTS.loginForbidden
  }
  return MFA_TEXTS.loginFailed
}
